function fadeAudio(target,duration,done){cancelAnimationFrame(audioFade);const from=ambientAudio.volume,start=performance.now();function step(now){const progress=Math.min(1,(now-start)/duration),ease=progress*progress*(3-2*progress);ambientAudio.volume=from+(target-from)*ease;if(progress<1)audioFade=requestAnimationFrame(step);else{audioFade=0;done?.()}}audioFade=requestAnimationFrame(step)}
